def consume_stock(stock, requests):
    for item, quantity in requests:
        stock[item] -= quantity
    return stock

cases.checks:
x = {'a': 5, 'b': 2}
assert s.consume_stock(x, [('a', 2), ('a', 3), ('b', 0)]) is x
assert x == {'a': 0, 'b': 2}
for requests, error in [([('a', 2), ('a', 4)], ValueError), ([('a', 1), ('b', -1)], ValueError), ([('a', 1), ('z', 0)], KeyError)]:
    x = {'a': 5, 'b': 2}
    try: s.consume_stock(x, requests)
    except error: pass
    else: raise AssertionError('invalid batch accepted')
    assert x == {'a': 5, 'b': 2}
x = {'a': 5}
assert s.consume_stock(x, []) is x

a = {'id': [1], 'v': 'first'}
b = {'id': [2], 'v': 'second'}
c = {'id': [1], 'v': 'later'}
x = [a, b, c]
r = s.unique_records(x, 'id')
assert r == [a, b] and r[0] is a and r[1] is b
assert x == [a, b, c] and a == {'id': [1], 'v': 'first'}
assert s.unique_records([{'id': {'x': 1}}, {'id': {'x': 1}}], 'id') == [{'id': {'x': 1}}]
assert s.unique_records([], 'id') == []
try: s.unique_records([{'other': 1}], 'id')
except KeyError: pass
else: raise AssertionError('missing field accepted')
